 */
public struct VibeFfiDelta {
    public var chatId: String
    /**
     * The generation this delta applies *to*. A consumer holding a different
     * generation must resync rather than apply.
     */
    public var baseGeneration: UInt64
    public var generation: UInt64
    public var body: VibeFfiDeltaBody
    /**
     * Bounds *after* applying the body.
     */
    public var bounds: VibeFfiBounds
    public var unreadCount: UInt32
    public var firstUnreadId: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(chatId: String, 
        /**
         * The generation this delta applies *to*. A consumer holding a different
         * generation must resync rather than apply.
         */baseGeneration: UInt64, generation: UInt64, body: VibeFfiDeltaBody, 
        /**
         * Bounds *after* applying the body.
         */bounds: VibeFfiBounds, unreadCount: UInt32, firstUnreadId: String?) {
        self.chatId = chatId
        self.baseGeneration = baseGeneration
        self.generation = generation
        self.body = body
        self.bounds = bounds
        self.unreadCount = unreadCount
        self.firstUnreadId = firstUnreadId
    }
}



extension VibeFfiDelta: Equatable, Hashable {
    public static func ==(lhs: VibeFfiDelta, rhs: VibeFfiDelta) -> Bool {
        if lhs.chatId != rhs.chatId {
            return false
        }
        if lhs.baseGeneration != rhs.baseGeneration {
            return false
        }
        if lhs.generation != rhs.generation {
            return false
        }
        if lhs.body != rhs.body {
            return false
        }
        if lhs.bounds != rhs.bounds {
            return false
        }
        if lhs.unreadCount != rhs.unreadCount {
            return false
        }
        if lhs.firstUnreadId != rhs.firstUnreadId {
            return false
        }
        return true
    }

