    public var tsMs: Int64
    /**
     * Dense index within the window this snapshot was built for. Derived —
     * never use it as a sort key.
     */
    public var orderSeq: UInt64
    public var authorUserId: String
    public var authorIsMe: Bool
    /**
     * Set for agent/bridge turns (`claude`, `codex`, …).
     */
    public var authorAgentProvider: String?
    public var kind: VibeFfiMessageKind
    public var text: String
    public var caption: String?
    /**
     * Raw [`vibe_core::types::VibeMessageFlags`] bits. Kept as a bitmask rather
     * than expanded to a dozen booleans so adding a flag is an additive change
     * on both sides of the boundary.
     */
    public var flags: UInt32
    public var displayStatus: VibeFfiDisplayStatus
    /**
     * `Some(0.0..=1.0)` while an upload is in flight.
     */
    public var uploadFraction: Float?
    public var deliveryFailed: Bool
    /**
     * FNV-1a over the rendered fields. A renderer can skip a reconfigure when
     * this is unchanged.
     */
    public var contentHash: UInt64
    public var hasMedia: Bool
    public var hasReply: Bool
    public var hasAgent: Bool
    public var hasService: Bool
    public var isEdited: Bool
    public var media: VibeFfiMedia?
    public var reply: VibeFfiReply?
    public var agent: VibeFfiAgent?
    public var service: VibeFfiService?
    public var editedAtMs: Int64?
    public var reactions: [VibeFfiReaction]
