         * on both sides of the boundary.
         */flags: UInt32, displayStatus: VibeFfiDisplayStatus, 
        /**
         * `Some(0.0..=1.0)` while an upload is in flight.
         */uploadFraction: Float?, deliveryFailed: Bool, 
        /**
         * FNV-1a over the rendered fields. A renderer can skip a reconfigure when
         * this is unchanged.
         */contentHash: UInt64, hasMedia: Bool, hasReply: Bool, hasAgent: Bool, hasService: Bool, isEdited: Bool, media: VibeFfiMedia?, reply: VibeFfiReply?, agent: VibeFfiAgent?, service: VibeFfiService?, editedAtMs: Int64?, reactions: [VibeFfiReaction], viewCount: UInt64?) {
        self.messageId = messageId
        self.clientMessageId = clientMessageId
        self.tsMs = tsMs
        self.orderSeq = orderSeq
        self.authorUserId = authorUserId
        self.authorIsMe = authorIsMe
        self.authorAgentProvider = authorAgentProvider
        self.kind = kind
        self.text = text
        self.caption = caption
        self.flags = flags
        self.displayStatus = displayStatus
        self.uploadFraction = uploadFraction
        self.deliveryFailed = deliveryFailed
        self.contentHash = contentHash
        self.hasMedia = hasMedia
        self.hasReply = hasReply
        self.hasAgent = hasAgent
        self.hasService = hasService
        self.isEdited = isEdited
        self.media = media
        self.reply = reply
        self.agent = agent
        self.service = service
        self.editedAtMs = editedAtMs
        self.reactions = reactions
        self.viewCount = viewCount
    }
}



