/**
 * One ordered mutation.
 *
 * `EvictHead`/`EvictTail` stay distinct from `Remove` across the boundary on
 * purpose: collapsing them is how a scroll-back trim gets a delete animation.
 */

public enum VibeFfiOp {
    
    case insert(index: UInt32, message: VibeFfiMessage
    )
    case remove(index: UInt32, messageId: String
    )
    case remapIdentity(index: UInt32, previousMessageId: String, message: VibeFfiMessage
    )
    /**
     * Same geometry — reconfigure pixels only.
     */
    case updateContent(index: UInt32, message: VibeFfiMessage, changed: UInt32
    )
    /**
     * May change height — the renderer must preserve the anchor across it.
     */
    case updateGeometry(index: UInt32, message: VibeFfiMessage, changed: UInt32
    )
    /**
     * Index-only relocation; content unchanged. Never animate as remove+insert.
     */
    case move(from: UInt32, to: UInt32, messageId: String
    )
    /**
     * Window trim, **not** a deletion. Must not animate.
     */
    case evictHead(count: UInt32
    )
    case evictTail(count: UInt32
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeVibeFfiOp: FfiConverterRustBuffer {
    typealias SwiftType = VibeFfiOp

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> VibeFfiOp {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .insert(index: try FfiConverterUInt32.read(from: &buf), message: try FfiConverterTypeVibeFfiMessage.read(from: &buf)
        )
        
        case 2: return .remove(index: try FfiConverterUInt32.read(from: &buf), messageId: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .remapIdentity(index: try FfiConverterUInt32.read(from: &buf), previousMessageId: try FfiConverterString.read(from: &buf), message: try FfiConverterTypeVibeFfiMessage.read(from: &buf)
        )
        
        case 4: return .updateContent(index: try FfiConverterUInt32.read(from: &buf), message: try FfiConverterTypeVibeFfiMessage.read(from: &buf), changed: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 5: return .updateGeometry(index: try FfiConverterUInt32.read(from: &buf), message: try FfiConverterTypeVibeFfiMessage.read(from: &buf), changed: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 6: return .move(from: try FfiConverterUInt32.read(from: &buf), to: try FfiConverterUInt32.read(from: &buf), messageId: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .evictHead(count: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 8: return .evictTail(count: try FfiConverterUInt32.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: VibeFfiOp, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .insert(index,message):
            writeInt(&buf, Int32(1))
            FfiConverterUInt32.write(index, into: &buf)
            FfiConverterTypeVibeFfiMessage.write(message, into: &buf)
            
        
        case let .remove(index,messageId):
            writeInt(&buf, Int32(2))
            FfiConverterUInt32.write(index, into: &buf)
            FfiConverterString.write(messageId, into: &buf)
            
        
        case let .remapIdentity(index,previousMessageId,message):
            writeInt(&buf, Int32(3))
            FfiConverterUInt32.write(index, into: &buf)
            FfiConverterString.write(previousMessageId, into: &buf)
            FfiConverterTypeVibeFfiMessage.write(message, into: &buf)
            
        
        case let .updateContent(index,message,changed):
            writeInt(&buf, Int32(4))
            FfiConverterUInt32.write(index, into: &buf)
            FfiConverterTypeVibeFfiMessage.write(message, into: &buf)
            FfiConverterUInt32.write(changed, into: &buf)
            
        
        case let .updateGeometry(index,message,changed):
            writeInt(&buf, Int32(5))
            FfiConverterUInt32.write(index, into: &buf)
            FfiConverterTypeVibeFfiMessage.write(message, into: &buf)
            FfiConverterUInt32.write(changed, into: &buf)
            
        
        case let .move(from,to,messageId):
            writeInt(&buf, Int32(6))
            FfiConverterUInt32.write(from, into: &buf)
            FfiConverterUInt32.write(to, into: &buf)
            FfiConverterString.write(messageId, into: &buf)
            
        
        case let .evictHead(count):
            writeInt(&buf, Int32(7))
            FfiConverterUInt32.write(count, into: &buf)
            
        
        case let .evictTail(count):
            writeInt(&buf, Int32(8))
            FfiConverterUInt32.write(count, into: &buf)
            
        }
    }
}


